import { DisplayObject } from "./DisplayObject";
import { Graphics } from "./Graphics";
import { BitmapData } from "./BitmapData";
import { execute as shapeClearBitmapBufferService } from "./Shape/usecase/ShapeClearBitmapBufferUseCase";
import { execute as shapeSetBitmapBufferUseCase } from "./Shape/usecase/ShapeSetBitmapBufferUseCase";
import { execute as shapeLoadSrcUseCase } from "./Shape/usecase/ShapeLoadSrcUseCase";
import { execute as shapeBuildFromCharacterUseCase } from "./Shape/usecase/ShapeBuildFromCharacterUseCase";
import { $graphicMap, $getArray } from "./DisplayObjectUtil";
/**
 * @description Shape クラスは、ベクターグラフィックスを表示するための表示オブジェクトです。
 *              The Shape class is a display object for displaying vector graphics.
 *
 * @class
 * @memberOf next2d.display
 * @extends  DisplayObject
 */
export class Shape extends DisplayObject {
    /**
     * @constructor
     * @public
     */
    constructor() {
        super();
        /**
         * @type {Graphics}
         * @default null
         * @private
         */
        Object.defineProperty(this, "_$graphics", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @type {string}
         * @default ""
         * @private
         */
        Object.defineProperty(this, "_$src", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description Shapeの機能を所持しているかを返却
         *              Returns whether the display object has Shape functionality.
         *
         * @type {boolean}
         * @readonly
         * @public
         */
        Object.defineProperty(this, "isShape", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description ビルドされたキャッシュキー
         *              Built cache key
         *
         * @type {number}
         * @default 0
         * @public
         */
        Object.defineProperty(this, "cacheKey", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description キャッシュのビルドに利用されるパラメータ
         *              Parameters used to build the cache
         *
         * @type {number[]}
         * @public
         */
        Object.defineProperty(this, "cacheParams", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description ビットマップ描画の判定フラグ
         *              Bitmap drawing judgment flag
         *
         * @type {boolean}
         * @default false
         * @protected
         */
        Object.defineProperty(this, "isBitmap", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        /**
         * @description 画像RGBAのUint8Array
         *              Image RGBA Uint8Array
         *
         * @type {Uint8Array|null}
         * @default null
         * @protected
         */
        Object.defineProperty(this, "$bitmapBuffer", {
            enumerable: true,
            configurable: true,
            writable: true,
            value: void 0
        });
        this.isShape = true;
        this.cacheKey = 0;
        this.cacheParams = $getArray(0, 0, 0);
        // private
        this._$graphics = null;
        this._$src = "";
        // bitmap
        this.$bitmapBuffer = null;
        this.isBitmap = false;
    }
    /**
     * @description 指定されたクラスの空間名を返します。
     *              Returns the space name of the specified class.
     *
     * @return {string}
     * @const
     * @static
     */
    static get namespace() {
        return "next2d.display.Shape";
    }
    /**
     * @description 指定されたオブジェクトの空間名を返します。
     *              Returns the space name of the specified object.
     *
     * @return {string}
     * @const
     * @public
     */
    get namespace() {
        return "next2d.display.Shape";
    }
    /**
     * @description この Shape オブジェクトに描画されるベクターの描画コマンドを保持する Graphics オブジェクトです。
     *              The Graphics object that belongs to this Shape object, where vector drawing commands can occur.
     *
     * @member  {Graphics}
     * @readonly
     * @public
     */
    get graphics() {
        if (!this._$graphics) {
            this._$graphics = new Graphics();
            $graphicMap.set(this._$graphics, this);
        }
        return this._$graphics;
    }
    /**
     * @description 指定されたパスから画像を読み込み、Graphicsを生成します
     *              Reads images from the specified path and generates Graphics.
     *
     * @member  {string}
     * @readonly
     * @public
     */
    get src() {
        return this._$src;
    }
    set src(src) {
        if (this._$src === src) {
            return;
        }
        this._$src = src;
        shapeLoadSrcUseCase(this, src);
    }
    /**
     * @description ビットマップデータを返します
     *              Returns the bitmap data.
     *
     * @return {BitmapData}
     * @readonly
     * @public
     */
    get bitmapData() {
        const bitmapData = new BitmapData(this.width, this.height);
        if (this.$bitmapBuffer) {
            bitmapData.buffer = this.$bitmapBuffer;
        }
        return bitmapData;
    }
    /**
     * @description ビットマップデータを解放します
     *              Releases bitmap data.
     *
     * @return {void}
     * @method
     * @public
     */
    clearBitmapBuffer() {
        shapeClearBitmapBufferService(this);
    }
    /**
     * @description RGBAの画像データを設定します
     *              Sets the RGBA image data.
     *
     * @param {number} width
     * @param {number} height
     * @param {Uint8Array} buffer
     * @method
     * @public
     */
    setBitmapBuffer(width, height, buffer) {
        shapeSetBitmapBufferUseCase(this, width, height, buffer);
    }
    /**
     * @description character 情報を元に DisplayObject を構築
     *              Build DisplayObject based on character
     *
     * @param  {ICharacter} character
     * @param  {LoaderInfo} [loader_info=null]
     * @return {void}
     * @method
     * @protected
     */
    $sync(character, loader_info = null) {
        if (loader_info) {
            super.$syncLoaderInfo(loader_info);
        }
        shapeBuildFromCharacterUseCase(this, character);
    }
}
